-- Work456/07: SQL seam only. Shell separately observes its actual records.
-- Full-value literal expectations come from the independently written model.
create table alt_rows(id int primary key,note int not null,payload bit varying(50000) not null storage prefer_inline);
create table alt_source(id int primary key,note int,payload bit varying(50000));
insert into alt_rows values(1,101,X'19ab23cd45ef'),(2,202,X'29bc34de56fa'),(3,303,cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying)),(4,404,cast(concat(repeat('d4',1801),repeat('e5',1803),repeat('f6',1803)) as bit varying));
insert into alt_source values(1,111,X'29bc34de56fa'),(2,212,cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying)),(3,313,X'19ab23cd45ef'),(4,414,cast(concat(repeat('d4',1801),repeat('e5',1803),repeat('f6',1803)) as bit varying)),(5,515,X'19ab23cd45ef'),(6,616,cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying));
merge into alt_rows t using alt_source s on t.id=s.id when matched then update set t.note=s.note,t.payload=s.payload when not matched then insert values(s.id,s.note,s.payload);
select count(*) as row_count,sum(case when id=1 and note=111 and payload=X'29bc34de56fa' then 1 when id=2 and note=212 and payload=X'' then 1 when id=3 and note=313 and payload=X'19ab23cd45ef' then 1 when id=4 and note=414 and payload=X'' then 1 when id=5 and note=515 and payload=X'19ab23cd45ef' then 1 when id=6 and note=616 and payload=X'' then 1 else 0 end) as exact_rows from alt_rows;
drop table alt_source;
drop table alt_rows;
